'use client';
import{useEffect,useRef,useState,useSyncExternalStore}from'react';
import{connectEventStream}from'./stream.js';
export function useAgentStore(store,selector){
const read=()=>selector(store.getSnapshot());
return useSyncExternalStore(store.subscribe,read,read);
}
export function useAgentStream(store,options){
const[status,setStatus]=useState('closed');
const latest=useRef(options);
latest.current=options;
const url=options?String(options.url):null;
useEffect(()=>{
const current=latest.current;
if(!current||url===null){
setStatus('closed');
return;
}
const controller=new AbortController();
connectEventStream({...current,store,signal:controller.signal,onStatus:(next)=>setStatus(next)});
return()=>controller.abort();
},[store,url]);
return status;
}
